// ===================== PIX BR CODE =====================
function emv(id,val){var l=String(val.length).padStart(2,'0');return id+l+val;}
function sanitizeStr(s,max){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9 ]/g,'').trim().substring(0,max).toUpperCase();}
function crc16(p){var c=0xffff;for(var i=0;i<p.length;i++){c^=p.charCodeAt(i)<<8;for(var j=0;j<8;j++){c=c&0x8000?((c<<1)^0x1021)&0xffff:(c<<1)&0xffff;}}return c.toString(16).toUpperCase().padStart(4,'0');}
function genPix(amount,txid){txid=txid||'***';var ma=emv('26',emv('00','br.gov.bcb.pix')+emv('01',CONFIG.PIX_KEY));var p=emv('00','01')+ma+emv('52','0000')+emv('53','986');if(amount>0){p+=emv('54',amount.toFixed(2));}p+=emv('58','BR')+emv('59',sanitizeStr(CONFIG.MERCHANT_NAME,25))+emv('60',sanitizeStr(CONFIG.MERCHANT_CITY,15));p+=emv('62',emv('05',txid.substring(0,25)))+'6304';return p+crc16(p);}

// ===================== SHA-256 =====================
async function sha256(text){var d=new TextEncoder().encode(text);var h=await crypto.subtle.digest('SHA-256',d);return Array.from(new Uint8Array(h)).map(function(b){return b.toString(16).padStart(2,'0');}).join('');}

// ===================== FRETE CORREIOS =====================
async function calcShipping(cep,weight){var services={PAC:'04510',SEDEX:'04014'};var results=[];
for(var name in services){var code=services[name];var params=new URLSearchParams({sCepOrigem:CONFIG.ORIGIN_CEP,sCepDestino:cep.replace(/\D/g,''),nVlPeso:String(weight||0.3),nCdFormato:'1',nVlComprimento:'20',nVlAltura:'10',nVlLargura:'15',nCdServico:code,nCdEmpresa:'',sDsSenha:'',nVlDiametro:'0',sCdMaoPropria:'n',StrRetorno:'xml'});
try{var res=await fetch('https://ws.correios.com.br/calculador/CalcPrecoPrazo.aspx?'+params);var xml=await res.text();var valorM=xml.match(/<Valor>([\d,.]+)<\/Valor>/);var prazoM=xml.match(/<PrazoEntrega>(\d+)<\/PrazoEntrega>/);
if(valorM){results.push({code:parseInt(code),name:name,price:parseFloat(valorM[1].replace(',','.')),days:prazoM?parseInt(prazoM[1]):0});}}catch(e){}}
results.unshift({code:0,name:'Retirar na Loja',price:0,days:0});return results;}

// ===================== CORS =====================
var CORS={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type'};
function json(d,s){s=s||200;return new Response(JSON.stringify(d),{status:s,headers:Object.assign({'Content-Type':'application/json'},CORS)});}

// ===================== WORKER PRINCIPAL =====================
export default {
  async fetch(request) {
    var url=new URL(request.url),path=url.pathname;
    if(request.method==='OPTIONS'){return new Response(null,{headers:CORS});}

    // API: Pix
    if(path==='/api/pix'&&request.method==='POST'){try{var b=await request.json();var amount=parseFloat(b.amount)||0;var payload=genPix(amount,b.txid);return json({success:true,payload:payload,qrUrl:'https://api.qrserver.com/v1/create-qr-code/?size=280x280&data='+encodeURIComponent(payload),amount:amount,beneficiary:CONFIG.MERCHANT_NAME});}catch(e){return json({success:false,error:e.message},400);}}

    // API: Admin Login
    if(path==='/api/admin-login'&&request.method==='POST'){try{var b=await request.json();var hash=await sha256(CONFIG.ADMIN_SALT+(b.password||''));await new Promise(function(r){setTimeout(r,300);});var ok=hash===CONFIG.ADMIN_PASS_SHA256;return json({success:ok,error:ok?undefined:'Credenciais invalidas'});}catch(e){return json({success:false,error:'payload invalido'},400);}}

    // API: Leads
    if(path==='/api/leads'&&request.method==='POST'){try{var b=await request.json();if(!b.name||!b.phone||!b.product){return json({error:'Campos obrigatorios'},400);}return json({ok:true,received:Object.assign({},b,{date:new Date().toISOString()})});}catch(e){return json({error:'payload invalido'},400);}}

    // API: Pix Confirm
    if(path==='/api/pix-confirm'&&request.method==='POST'){try{var b=await request.json();var order={txid:b.txid||'',amount:b.amount||0,customerName:b.customerName||'Cliente',customerPhone:b.customerPhone||'',items:b.items||[],status:'confirmed',confirmedAt:new Date().toISOString()};
var storeMsg='\u2705 *PAGAMENTO PIX CONFIRMADO!*\n\n*Cliente:* '+order.customerName+'\n*WhatsApp:* '+order.customerPhone+'\n*Valor:* R$ '+order.amount.toFixed(2).replace('.',',')+'\n\n*Itens:*\n'+order.items.map(function(i){return i.qty+'x '+i.name+' R$ '+(i.price*i.qty).toFixed(2);}).join('\n');
var customerMsg='\u2705 *PAGAMENTO CONFIRMADO - MIMI MIMOS!*\n\nOla '+order.customerName+'! Recebemos seu pagamento de R$ '+order.amount.toFixed(2).replace('.',',')+'.\nSeu pedido esta confirmado!';
var storeWa='https://wa.me/'+CONFIG.WHATSAPP_NUMBER+'?text='+encodeURIComponent(storeMsg);
var customerWa=order.customerPhone?'https://wa.me/'+order.customerPhone.replace(/\D/g,'')+'?text='+encodeURIComponent(customerMsg):null;
return json({success:true,order:order,notifications:{store:{whatsapp:storeWa},customer:customerWa?{whatsapp:customerWa}:null}});}catch(e){return json({success:false,error:e.message},400);}}

    // API: Products
    if(path==='/api/products'){return json({success:true,count:PERFUMES.length,products:PERFUMES});}

    // API: Promotions
    if(path==='/api/promotions'){var promos=[{id:'promo-3decantes',type:'combo',title:'3 Decantes por R$ 100',message:'Combo especial: leve 3 decantes por R$ 100!',active:true},{id:'promo-miniaturas',type:'combo',title:'Miniaturas Afeer',message:'Miniaturas arabes Afeer a partir de R$ 79,99!',active:true}];return json({promotions:promos,count:promos.length});}

    // API: Shipping
    if(path==='/api/shipping'&&request.method==='GET'){var cep=url.searchParams.get('cep');if(!cep||cep.replace(/\D/g,'').length!==8){return json({error:'CEP invalido'},400);}var options=await calcShipping(cep,0.3);return json({cep:cep,options:options});}

    // API: Health
    if(path==='/api/health'){return json({status:'ok',service:'Mimi Mimos',runtime:'cloudflare-workers',products:PERFUMES.length});}

    // Manifest
    if(path==='/manifest.json'){return new Response(JSON.stringify({name:'Mimi Mimos',short_name:'Mimi Mimos',start_url:'/',display:'standalone',background_color:'#090a0f',theme_color:'#090a0f',icons:[{src:CONFIG.LOGO,sizes:'192x192',type:'image/png'}]}),{headers:{'Content-Type':'application/json'}});}

    // HTML principal
    return new Response(renderHTML(),{headers:{'Content-Type':'text/html;charset=UTF-8'}});
  }
};

